(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["ml"] = {"ui":{"skip":"ഉള്ളടക്കത്തിലേക്ക് പോകുക","back":"← AI-gile-ലേക്ക് മടങ്ങുക","lang.button":"ഭാഷ: {name}","lang.dialog":"ഒരു ഭാഷ തിരഞ്ഞെടുക്കുക","lang.search":"ഭാഷകൾ തിരയുക","lang.none":"ചേരുന്ന ഭാഷയില്ല","lang.notYet":"{name} ഇതുവരെ വിവർത്തനം ചെയ്തിട്ടില്ല","theme.aria":"ലൈറ്റ്, ഡാർക്ക് തീമുകൾക്കിടയിൽ മാറുക","theme.toLight":"ലൈറ്റ് തീമിലേക്ക് മാറുക","theme.toDark":"ഡാർക്ക് തീമിലേക്ക് മാറുക","index.title":"AI-gile: നിങ്ങളുടെ AI ഡെവ് ടീം, ഒരൊറ്റ ബോർഡിൽ","index.description":"AI കോഡിങ് ടീമുകൾക്കുള്ള ഒരു കാൻബൻ ബോർഡാണ് AI-gile. നിങ്ങൾ ഉറങ്ങുമ്പോൾ അവർ ജോലി ചെയ്യുന്നു; നിങ്ങൾക്ക് ബാക്കിയാകുന്നത് ഒരു ചെറിയ കൂമ്പാരം: തീരുമാനിക്കാനും പരീക്ഷിക്കാനും സ്വീകരിക്കാനുമുള്ളവ.","hero.logoAlt":"AI-gile ബോർഡ് ഐക്കൺ","hero.h1.html":"നിങ്ങളുടെ AI ഡെവ് ടീം, ഒരൊറ്റ&nbsp;ബോർഡിൽ.","hero.alpha":"🐣 അടച്ച പ്രീ-ആൽഫ","hero.alphaTitle":"തുടക്കത്തിലുള്ളതും പൂർത്തിയാകാത്തതും: പരീക്ഷിക്കുന്നതിന് നന്ദി!","hero.lede":"നിങ്ങൾ ഉറങ്ങുമ്പോൾ അവർ നിർമ്മിക്കുന്നു. ഉണരുമ്പോൾ ഒരു ചെറിയ കൂമ്പാരം കാണാം: കുറച്ച് ചോദ്യങ്ങൾ, പരീക്ഷിക്കാൻ ചിലത്, ഒന്നോ രണ്ടോ വയലറ്റ് വജ്രങ്ങൾ. ക്ലിക്ക് ചെയ്യുക, സ്വീകരിക്കുക, കാപ്പിയിലേക്ക് മടങ്ങുക.","dl.windows":"Windows ആപ്പ്","dl.browser":"ബ്രൗസറിൽ പ്രവർത്തിപ്പിക്കുക","dl.soon":"ഉടൻ വരുന്നു","dl.notify":"🔔 തുറക്കുമ്പോൾ എന്നെ അറിയിക്കുക","dl.notifySmall":"ആൽഫ അല്ലെങ്കിൽ ബീറ്റ","hero.secondary":"അജൈൽ തന്നെ, പക്ഷേ ടീമിന് സ്റ്റാൻഡ്-അപ്പ് കാപ്പി ഒരിക്കലും വേണ്ട. (സ്റ്റാൻഡ്-അപ്പുകൾ അവർ നടത്താറുണ്ട്.)","pitch.h2":"നിങ്ങൾക്ക് വേണ്ടത്ര വാക്കുകളിൽ AI-gile","pitch.lede":"ഒരു വാക്ക് മുതൽ 144 വരെ, നീളം തിരഞ്ഞെടുക്കുക. ഓരോ നീളവും ആ വലുപ്പത്തിനായി എഴുതിയ സ്വന്തം വിവരണമാണ്. സ്ലൈഡർ വലിക്കുകയോ ആരോ കീകൾ ഉപയോഗിക്കുകയോ ചെയ്യുക.","pitch.rangeLabel":"വാക്കുകളിലെ നീളം","pitch.dice":"🎲 മറ്റൊരു പതിപ്പ്","pitch.words.one":"{n} വാക്ക്","pitch.words.other":"{n} വാക്കുകൾ","pitch.letters.one":"{n} അക്ഷരം","pitch.letters.other":"{n} അക്ഷരങ്ങൾ","pitch.chars.one":"{n} ചിഹ്നം","pitch.chars.other":"{n} ചിഹ്നങ്ങൾ","count.line.html.one":"ഇപ്പോൾ ബോർഡിൽ {n} കാർഡ്","count.line.html.other":"ഇപ്പോൾ ബോർഡിൽ {n} കാർഡുകൾ","features.aria":"ഇത് എന്തു ചെയ്യുന്നു","f.pile.h":"നിങ്ങൾക്കായി ഒരു കൂമ്പാരം","f.pile.html":"<b>നിങ്ങൾക്ക്</b> എന്ന കോളത്തിൽ എല്ലാ പ്രോജക്റ്റുകളിൽ നിന്നും നിങ്ങളെ കാത്തിരിക്കുന്നതെല്ലാം ഉണ്ട്: ചോദ്യങ്ങൾ, പരീക്ഷിക്കാനുള്ളവ, മനുഷ്യന് മാത്രം ചെയ്യാവുന്ന ജോലികൾ. അടുത്തത് എന്തെന്നും അതിന് എത്ര സമയമെടുക്കുമെന്നും നിങ്ങളുടെ ക്യൂ പറയും.","f.sleep.h":"നിങ്ങൾ ഉറങ്ങുമ്പോൾ ജോലി ചെയ്യുന്ന ടീമുകൾ","f.sleep.p":"ഓരോ പ്രോജക്റ്റിനും ഒരു ലീഡും AI ഏജന്റുമാരുടെ ഒരു ടീമും ഉണ്ട്. ഒരു കാർഡിൽ കമന്റ് ഇടുക, ടീം ഉണർന്ന് ജോലി ചെയ്ത്, ക്ഷീണിച്ച മനുഷ്യനും പിന്തുടരാവുന്ന ഘട്ടങ്ങളോടെ അത് തിരികെ നൽകും.","f.tester.h":"ആദ്യം ഒരു AI ടെസ്റ്റർ പരിശോധിക്കും","f.tester.p":"എന്തെങ്കിലും നിങ്ങളുടെ അടുത്ത് എത്തുന്നതിന് മുമ്പ്, ടെസ്റ്റർ ആപ്പിന്റെ ഒരു പകർപ്പിൽ ഘട്ടങ്ങൾ പിന്തുടർന്ന് താൻ കണ്ടത് സ്ക്രീൻഷോട്ടോടെ കാണിക്കും. വിജയിച്ചവ മറിച്ചുനോക്കി ഒറ്റ ക്ലിക്കിൽ സ്വീകരിക്കുക.","f.proof.h":"വാഗ്ദാനമല്ല, തെളിവ്","f.proof.p":"ഓരോ കൈമാറ്റവും എന്താണ് മാറിയതെന്ന് കാണിക്കുന്നു: ഫയലുകൾ, വ്യത്യാസം, സ്ക്രീൻഷോട്ടുകൾ. പൂർത്തിയായോ എന്ന് നോക്കാൻ ഓരോ ആപ്പും തുറക്കേണ്ടതില്ല.","f.chat.h":"നിങ്ങളുടെ ലീഡുകളുമായി ചാറ്റ് ചെയ്യുക","f.chat.p":"Discord ശൈലിയിലുള്ള ഒരു റെയിൽ: ഓരോ പ്രോജക്റ്റിനും ഒരു ഐക്കൺ, നിങ്ങളെ ആവശ്യമുള്ളവയ്ക്ക് വയലറ്റ് വജ്രങ്ങൾ. ലീഡിന് ഒരു ആശയം അയയ്ക്കുക; അവർ അത് കാർഡുകളും പ്ലാനുമാക്കും, ഒരു ✅ പോകൂ ബട്ടണോടെ.","f.tidy.h":"സ്വയം വൃത്തിയാക്കുന്നു","f.tidy.p":"ബന്ധപ്പെട്ട കാർഡുകൾ ഒന്നായി ലയിക്കുന്നു, കുഴഞ്ഞ തലക്കെട്ടുകൾ ശരിയാക്കുന്നു, ടോക്കൺ പരിശോധന കോഡിനെ ഒതുക്കത്തിൽ നിർത്തുന്നു. മാറിമാറി നോക്കാൻ കുറച്ച് കാര്യങ്ങൾ, ചിന്തിക്കാൻ കുറവ്.","f.private.h":"നിങ്ങളുടേത്, നിങ്ങളുടെ കമ്പ്യൂട്ടറിൽ","f.private.li1":"ബോർഡ് നിങ്ങളുടെ സ്വന്തം കമ്പ്യൂട്ടറിൽ പ്രവർത്തിക്കുന്നു, നിങ്ങളോട് മാത്രം പ്രതികരിക്കുന്നു.","f.private.li2":"ആളുകൾ തമ്മിലുള്ള സ്വകാര്യ സന്ദേശങ്ങൾ എൻഡ്-ടു-എൻഡ് എൻക്രിപ്റ്റ് ചെയ്തതാണ്.","f.private.li3":"അക്കൗണ്ടുകളില്ല, ട്രാക്കറുകളില്ല, കുക്കികളില്ല.","f.lang.h":"നിങ്ങളുടെ ഭാഷയിൽ","f.lang.p":"ഡച്ച്, വെൽഷ്, ജാപ്പനീസ് മുതൽ കടൽക്കൊള്ളക്കാരൻ, യോഡ, ക്ലിംഗൺ വരെ 120-ലധികം ഭാഷകൾ, ഡെവലപ്പർ വാക്കുകൾക്കായി ഇംഗ്ലീഷിലേക്ക് വേഗത്തിൽ മടങ്ങാനുള്ള സൗകര്യത്തോടെ.","tl.aria":"ആദ്യ സംഭാഷണം മുതൽ റോഡ്മാപ്പ് വരെയുള്ള സമയരേഖ","tl.h2":"ആദ്യ ചാറ്റ് മുതൽ അടുത്തത് വരെ","tl.lede":"യഥാർത്ഥ തീയതികളും സമയങ്ങളും, നിങ്ങളുടെ സ്വന്തം സമയമേഖലയിൽ. ഇന്നിന് ശേഷം ഇത് പദ്ധതിയാണ്, തീയതികൾ ഉറപ്പ് നൽകുന്നില്ല.","tl.today":"ഇന്ന്","tl.planned":"ആസൂത്രണം ചെയ്തത്","tl.cards.one":"{n} കാർഡ്","tl.cards.other":"{n} കാർഡുകൾ","join.h2":"ഒപ്പം ചേരൂ","join.lede":"ഒരു ചെറിയ മനുഷ്യനും ക്ഷമയുള്ള ഒരുപാട് ഏജന്റുമാരും ചേർന്നാണ് AI-gile നിർമ്മിക്കുന്നത്. ഇപ്പോൾ ഇത് സ്വകാര്യമാണ്, സുഹൃത്തുക്കളോടൊപ്പം ഒരു അടച്ച ആൽഫയിൽ. തുറക്കുമ്പോൾ പരീക്ഷിക്കാൻ ആഗ്രഹമുണ്ടോ?","join.btn":"താൽപ്പര്യം രജിസ്റ്റർ ചെയ്യുക","join.small":"ഞങ്ങൾ ഇമെയിൽ അയയ്ക്കും, മറ്റൊന്നുമില്ല","footer.tag":"AI-gile. ട്രാക്കറുകളില്ല, കുക്കികളില്ല, സ്റ്റാൻഡ്-അപ്പ് കാപ്പിയില്ല.","footer.licence":"ബിസിനസ് ലൈസൻസ്","footer.status":"സ്റ്റാറ്റസ്","form.sending":"അയയ്ക്കുന്നു…","form.failed":"അത് നടന്നില്ല: പിന്നീട് വീണ്ടും ശ്രമിക്കുക.","form.offline":"AI-gile-ൽ എത്താൻ കഴിഞ്ഞില്ല: പിന്നീട് വീണ്ടും ശ്രമിക്കുക.","interest.title":"AI-gile: ആൽഫ തുറക്കുമ്പോൾ എന്നെ അറിയിക്കുക","interest.description":"AI-gile-ന്റെ അടച്ച ആൽഫയോ ബീറ്റയോ തുറക്കുന്നത് അറിയാൻ നിങ്ങളുടെ ഇമെയിൽ നൽകുക.","interest.h1":"🔔 തുറക്കുമ്പോൾ എന്നെ അറിയിക്കുക","interest.lede":"AI-gile അടച്ച പ്രീ-ആൽഫയിലാണ്. ഇമെയിൽ നൽകൂ, നിങ്ങൾക്കായി ഒരിടം ഉണ്ടാകുമ്പോൾ ഞങ്ങൾ ഒരിക്കൽ മാത്രം എഴുതാം.","interest.email":"നിങ്ങളുടെ ഇമെയിൽ","interest.which":"ഏത് ടെസ്റ്റ്?","interest.alpha":"അടച്ച ആൽഫ: തുടക്കം, പരുക്കൻ, ഒരുപാട് മാറ്റങ്ങൾ","interest.beta":"ബീറ്റ: കൂടുതൽ സ്ഥിരം, പിന്നീട്","interest.both":"ഏതായാലും, ആദ്യം വരുന്നത്","interest.submit":"എന്നെ പട്ടികയിൽ ചേർക്കൂ","interest.thanks":"നന്ദി! നിങ്ങൾ പട്ടികയിലുണ്ട്.","licence.title":"AI-gile: ബിസിനസ് ലൈസൻസ്","licence.description":"നിങ്ങളുടെ ബിസിനസിൽ AI-gile ഉപയോഗിക്കുന്നുണ്ടോ? സൗജന്യ ബിസിനസ് ലൈസൻസിന് അപേക്ഷിക്കുക.","licence.h1":"📜 ബിസിനസ് ലൈസൻസ്","licence.lede":"ജോലിസ്ഥലത്ത് AI-gile ഉപയോഗിക്കുന്നുണ്ടോ? നിങ്ങൾ ആരാണെന്നും എന്തു ചെയ്യുന്നുവെന്നും ഞങ്ങളോട് പറയൂ. അത് എന്തെങ്കിലും നന്മ ചെയ്യുന്നുവെങ്കിൽ ലൈസൻസ് സൗജന്യമാണ്.","licence.company":"കമ്പനി","licence.website":"വെബ്സൈറ്റ്","licence.what":"നിങ്ങൾ എന്തു ചെയ്യുന്നു","licence.how":"ഇത് ലോകത്തെ എങ്ങനെ സഹായിക്കുന്നു","licence.email":"ഇമെയിൽ","licence.submit":"അപേക്ഷിക്കുക","licence.thanks":"നന്ദി! ഞങ്ങൾ ഇമെയിലിൽ മറുപടി നൽകും.","status.title":"AI-gile സ്റ്റാറ്റസ്","status.h1":"AI-gile സ്റ്റാറ്റസ്","status.quiet":"എല്ലാം ശാന്തം","status.checking":"പരിശോധിക്കുന്നു…","status.offline":"സ്റ്റാറ്റസ് സേവനത്തിൽ ഇപ്പോൾ എത്താൻ കഴിയുന്നില്ല (വീണ്ടും ശ്രമിക്കുന്നു)","status.updated":"{ago} അപ്ഡേറ്റ് ചെയ്തു","status.justNow":"ഇപ്പോൾ","status.min":"{n} മിനിറ്റ് മുമ്പ്","status.hours":"{n} മണിക്കൂർ മുമ്പ്","status.days":"{n} ദിവസം മുമ്പ്","live.h2":"ഇത് നിർമ്മിക്കപ്പെടുന്നത് തത്സമയം കാണൂ","live.caption":"ഓരോ കാർഡും മറച്ചിരിക്കുന്നു: നിങ്ങൾ ജോലിയുടെ രൂപമാണ് കാണുന്നത്, വാക്കുകളല്ല.","live.watching.one":"തത്സമയം: {n} പേർ കാണുന്നു","live.watching.other":"തത്സമയം: {n} പേർ കാണുന്നു","live.offline":"തത്സമയ ബോർഡ് അൽപം വിശ്രമിക്കുകയാണ്. വൈകാതെ വീണ്ടും നോക്കൂ.","live.cols":"ബാക്ക്‌ലോഗ്|ചെയ്യാനുള്ളത്|പുരോഗമിക്കുന്നു|ടീം പരിശോധിക്കുന്നു|നിങ്ങൾ ടെസ്റ്റ് ചെയ്യാൻ|ടീമിന്|പൂർത്തിയായി","live.last.now":"അവസാന കാർഡ് ഇപ്പോൾ നീക്കി","live.last.min.one":"അവസാന കാർഡ് {n} മിനിറ്റ് മുമ്പ് നീക്കി","live.last.min.other":"അവസാന കാർഡ് {n} മിനിറ്റ് മുമ്പ് നീക്കി","live.last.hour.one":"അവസാന കാർഡ് {n} മണിക്കൂർ മുമ്പ് നീക്കി","live.last.hour.other":"അവസാന കാർഡ് {n} മണിക്കൂർ മുമ്പ് നീക്കി","live.last.day.one":"അവസാന കാർഡ് {n} ദിവസം മുമ്പ് നീക്കി","live.last.day.other":"അവസാന കാർഡ് {n} ദിവസം മുമ്പ് നീക്കി"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["കാൻബൻ.","റോബോട്ടുകൾ.","ഏൽപ്പിച്ചു."]},{"n":2,"texts":["റോബോട്ട് കാൻബൻ.","ഏജന്റുമാർ, ചിട്ടയോടെ.","ആശയങ്ങൾ, നിർമ്മിതം."]},{"n":3,"texts":["റോബോട്ടുകൾക്കായി ഒരു കാൻബൻ.","ആശയങ്ങൾ ഫീച്ചറുകളാകുന്നു.","സൗജന്യ ഏജന്റ് കാൻബൻ."]},{"n":5,"texts":["ഏജന്റുമാർ നടത്തുന്ന കാൻബൻ ബോർഡ്.","നിങ്ങൾ കാർഡുകൾ എഴുതുന്നു. ഏജന്റുമാർ നിർമ്മിക്കുന്നു.","സൗജന്യം, ലോക്കൽ, പരിശോധിച്ചത്, അൽപ്പം കോമാളി."]},{"n":8,"texts":["AI ഏജന്റുമാർ ജോലി ചെയ്യുന്ന ഒരു സൗജന്യ കാൻബൻ ബോർഡ്.","ഒരു ആശയം എഴുതൂ. ഏജന്റുമാർ അത് നിർമ്മിക്കും. നിങ്ങൾ സ്വീകരിക്കൂ.","ഒരു മനുഷ്യനും ക്ഷമയുള്ള ഒരുപാട് റോബോട്ടുകൾക്കുമുള്ള അജൈൽ."]},{"n":13,"texts":["നിങ്ങളുടെ കമ്പ്യൂട്ടറിലെ ഒരു കാൻബൻ ബോർഡ്, അവിടെ AI ഏജന്റുമാർ കാർഡുകൾ ഓരോന്നായി ഏറ്റെടുക്കുന്നു.","ഒരു ആശയം എഴുതൂ. ഏജന്റുമാരുടെ ടീം അത് നിർമ്മിക്കും. ഒരു ടെസ്റ്റർ പരിശോധിച്ച് കാണിക്കും.","അക്കൗണ്ടില്ല, ട്രാക്കറില്ല: ഒരു ബോർഡ്, കുറച്ച് റോബോട്ടുകൾ, ഒടുവിൽ എല്ലാം തീരുമാനിക്കുന്ന നിങ്ങൾ തന്നെ."]},{"n":21,"texts":["AI-gile, AI കോഡിങ് ഏജന്റുമാരോടൊപ്പം പ്രവർത്തിക്കാനുള്ള ഒരു സൗജന്യ കാൻബൻ ബോർഡാണ്. അവർ കാർഡുകൾ ഓരോന്നായി ഏറ്റെടുക്കുന്നു; നിങ്ങൾ അവ പരീക്ഷിച്ച് ഒടുവിൽ സ്വീകരിക്കുന്നു.","ഓരോ പ്രോജക്റ്റിനും സ്വന്തമായി ഒരു ലീഡും AI ഏജന്റുമാരുടെ ടീമും ഉണ്ട്. ഏതെങ്കിലും കാർഡിൽ കമന്റ് ഇട്ടാൽ ടീം ഉടൻ തന്നെ ജോലി തുടങ്ങും.","ഇത് നിങ്ങളുടെ സ്വന്തം കമ്പ്യൂട്ടറിൽ പ്രവർത്തിക്കുന്ന സൗജന്യ വ്യക്തിഗത ടു-ഡു ബോർഡാണ്. ജോലിക്കാർ എല്ലാം റോബോട്ടുകൾ. അവസാനമായി “ശരി” എന്ന് പറയുന്നത് നിങ്ങൾ മാത്രം."]},{"n":34,"texts":["നിങ്ങൾ ആശയങ്ങൾ ബോർഡിൽ ഇടുന്നു. AI ഏജന്റുമാരുടെ ഒരു ടീം അവയെ പ്രവർത്തിക്കുന്ന ഫീച്ചറുകളാക്കി മാറ്റി, പരിശോധിച്ച്, പരീക്ഷിച്ചുനോക്കാനുള്ള ഘട്ടങ്ങളോടെ തിരികെ നൽകുന്നു. നിങ്ങൾ പറയുന്നതുവരെ ഒന്നും പൂർത്തിയായതായി കണക്കാക്കില്ല. ഒന്നും നിങ്ങൾ കാണാതെ പൂർത്തിയാകുന്നില്ല, ഒന്നും ഒളിപ്പിക്കുന്നുമില്ല.","AI-gile, Rich വീട്ടിലിരുന്ന് ഉണ്ടാക്കിയ ഒരു കാൻബൻ ബോർഡാണ്; ഇപ്പോൾ അത് നിയന്ത്രിക്കുന്ന ഏജന്റുമാരുടെ വലിയ സഹായത്തോടെയാണ് അത് നിർമ്മിച്ചത്. ഇത് സൗജന്യമാണ്, നിങ്ങളുടെ കമ്പ്യൂട്ടറിൽ പ്രവർത്തിക്കുന്നു, സുഹൃത്തുക്കളുമായി പങ്കിടുന്നു, വിൽക്കുന്നില്ല. ഒറ്റയ്ക്കുള്ള ഒരു ചെറിയ പദ്ധതി, ഒരു കമ്പനിയല്ല.","ബാക്ക്‌ലോഗ് മുതൽ പൂർത്തിയായി വരെ കോളങ്ങളുള്ള ഒരു സാധാരണ കാൻബൻ ബോർഡ് സങ്കൽപ്പിക്കുക, പക്ഷേ കാർഡുകൾ ഏറ്റെടുക്കുന്നത് മനുഷ്യരല്ല, AI ഏജന്റുമാരാണ്. അവർ പുരോഗതി അറിയിക്കുന്നു, കുടുങ്ങിയാൽ ചോദിക്കുന്നു, നിങ്ങളുടെ അനുമതിക്കായി എപ്പോഴും കാത്തിരിക്കുന്നു. ഒന്നും ഒളിച്ചുവയ്ക്കുന്നില്ല."]},{"n":55,"texts":["AI-gile, ടീമിലെ അംഗങ്ങൾ AI ഏജന്റുമാരായ ഒരു കാൻബൻ ബോർഡാണ്. ഓരോ പ്രോജക്റ്റിനും ജോലി ആസൂത്രണം ചെയ്യുന്ന ഒരു ലീഡും അത് നിർമ്മിക്കുന്ന സഹായികളും ഉണ്ട്. ഒരു ഫീച്ചർ തയ്യാറാകുമ്പോൾ ഒരു AI ടെസ്റ്റർ അത് പരീക്ഷിച്ച് സ്ക്രീൻഷോട്ട് എടുക്കുന്നു, പിന്നെ അത് നിങ്ങളുടെ കൂമ്പാരത്തിൽ എത്തുന്നു. സ്വീകരിക്കുക, അല്ലെങ്കിൽ കമന്റ് ഇടുക, അവർ അത് വീണ്ടും പണിയും. എല്ലാം ഒരേ ബോർഡിൽ.","ഒരുപാട് AI കോഡിങ് സെഷനുകൾ ഒരേസമയം ഒരാൾക്ക് നോക്കിനടത്താനുള്ള വഴിയായി ഇത് തുടങ്ങി, പിന്നെ ഒരു ശരിക്കുള്ള ബോർഡായി വളർന്നു. ഇത് നിങ്ങളുടെ കമ്പ്യൂട്ടറിൽ പ്രവർത്തിക്കുന്നു, അക്കൗണ്ട് വേണ്ട, ട്രാക്കറുകളില്ല. സുഹൃത്തുക്കൾക്കും കൗതുകമുള്ള ആർക്കും ഇത് സൗജന്യമാണ്. ഇത് ഇനിയും പൂർത്തിയായിട്ടില്ല, അതിനാൽ പരുക്കൻ ഭാഗങ്ങളും ഇടയ്ക്കൊരു അത്ഭുതവും പ്രതീക്ഷിക്കുക. ഇതിന്റെ ലക്ഷ്യം ലളിതമാണ്: കുറച്ച് കാര്യങ്ങൾ മാത്രം നിങ്ങളുടെ ശ്രദ്ധയ്ക്ക് വിടുക, ബാക്കി ഏജന്റുമാർ നോക്കട്ടെ.","സത്യസന്ധമായ പതിപ്പ് ഇതാണ്. ആശയങ്ങൾ ഉണ്ടാക്കേണ്ടത് ഇപ്പോഴും നിങ്ങളാണ്, ഫലം പരിശോധിക്കേണ്ടതും നിങ്ങൾ തന്നെ. ഇടയിലുള്ള എല്ലാം AI-gile ചെയ്യുന്നു: കാർഡുകൾ ക്രമത്തിൽ സൂക്ഷിക്കുന്നു, നിങ്ങൾ കമന്റ് ഇടുമ്പോൾ ശരിയായ ഏജന്റിനെ ഉണർത്തുന്നു, കൃത്യമായി എന്താണ് മാറിയതെന്ന് കാണിക്കുന്നു, ഇതെല്ലാം നിങ്ങൾക്കായി ഒരു ചെറിയ കൂമ്പാരത്തിൽ ഒരുമിപ്പിക്കുന്നു. അങ്ങനെ പല ആപ്പുകൾക്കിടയിൽ മാറിമാറി ഓടേണ്ട, ഒന്നും മറന്നുപോകുകയുമില്ല, നിങ്ങളുടെ സമയം ലാഭിക്കുകയും ചെയ്യും. ഇതാണ് മുഴുവൻ കഥ."]},{"n":89,"texts":["AI-gile നിങ്ങളുടെ സ്വന്തം കമ്പ്യൂട്ടറിൽ പ്രവർത്തിപ്പിക്കാവുന്ന ഒരു സൗജന്യ കാൻബൻ ബോർഡാണ്. മനുഷ്യർക്ക് പകരം ഓരോ പ്രോജക്റ്റിനും AI ഏജന്റുമാരുടെ ഒരു ടീം ഉണ്ട്: നിങ്ങളുടെ ആശയങ്ങളെ കാർഡുകളും പ്ലാനുമാക്കുന്ന ഒരു ലീഡ്, മുൻഗണനാക്രമത്തിൽ കാർഡുകൾ ഏറ്റെടുക്കുന്ന സഹായികൾ. എന്തെങ്കിലും നിർമ്മിച്ചു കഴിഞ്ഞാൽ ഒരു AI ടെസ്റ്റർ പരീക്ഷണ ഘട്ടങ്ങൾ പിന്തുടർന്ന് താൻ കണ്ടത് നിങ്ങളെ കാണിക്കുന്നു. പിന്നെ അത് നിങ്ങൾക്ക് എന്ന ഒരു കൂമ്പാരത്തിൽ കാത്തിരിക്കുന്നു. നിങ്ങൾ സ്വീകരിക്കുന്നു, അല്ലെങ്കിൽ കമന്റ് ഇട്ടാൽ ടീം വീണ്ടും ശ്രമിക്കുന്നു. നിങ്ങളില്ലാതെ ഒന്നും പൂർത്തിയായി എന്നതിലേക്ക് എത്തില്ല. ഒന്നും ഒളിപ്പിക്കുന്നില്ല: ഓരോ കാർഡിലും ആരാണ് എന്ത് ചെയ്തു എന്ന് കാണാം, എല്ലാ മാറ്റങ്ങളും ഫയലുകളും സഹിതം.","നിങ്ങൾ പ്രതീക്ഷിക്കാത്ത ചില കാര്യങ്ങൾ. നിങ്ങൾ ഉറങ്ങുമ്പോൾ രാത്രി കാവൽ ചെയ്യാനുള്ളത് കോളം നിറച്ചുനിർത്തുന്നു, നിങ്ങളുടെ ഉത്തരം ആവശ്യമില്ലാത്ത കാർഡുകൾ തിരഞ്ഞെടുത്തുകൊണ്ട്. ഇന്നും ഈ ആഴ്ചയും ഏജന്റുമാർ എത്ര ഉപയോഗിച്ചെന്ന് ടോക്കൺ കൗണ്ടർ കാണിക്കുന്നു, ടോക്കൺ ഇല്ലാ മോഡ് ചെലവാക്കുന്നത് നിർത്താൻ അവരോട് പറയുന്നു. സുഹൃത്തുക്കൾക്ക് സന്ദേശം അയയ്ക്കാം, സ്വകാര്യ സന്ദേശങ്ങൾ എൻഡ്-ടു-എൻഡ് എൻക്രിപ്റ്റ് ചെയ്തതാണ്. ബോർഡ് ഏകദേശം 120 ഭാഷകൾ സംസാരിക്കുന്നു, ഡച്ച്, ഫ്ലെമിഷ്, കടൽക്കൊള്ളക്കാരൻ, ക്ലിംഗൺ ഉൾപ്പെടെ. ഇതൊന്നും പണം ചെലവാക്കേണ്ടതല്ല, ആരും ഇത് നിങ്ങൾക്ക് വിൽക്കാൻ ശ്രമിക്കുന്നുമില്ല. ഇതെല്ലാം നിങ്ങളുടെ സ്വന്തം കമ്പ്യൂട്ടറിൽ, നിങ്ങളുടെ നിയന്ത്രണത്തിൽ നടക്കുന്നു, മറ്റാരുടെയും സെർവറിൽ അല്ല. ആവശ്യമുള്ളപ്പോൾ മാത്രം ഇന്റർനെറ്റ് വേണം.","AI-gile ഒരു കമ്പനിയല്ല, ചെറിയ വ്യക്തിഗത പ്രോജക്റ്റാണ്. ഓരോ ആപ്പും തുറന്ന് പരിശോധിക്കാതെ പല AI കോഡിങ് പ്രോജക്റ്റുകൾ നോക്കണമെന്ന് Rich ആഗ്രഹിച്ചു, അതിനാൽ അദ്ദേഹവും ഏജന്റുമാരും അതിനായി ഒരു ബോർഡ് ഉണ്ടാക്കി, പിന്നെ ബാക്കി ഭാഗം ആ ബോർഡ് ഉപയോഗിച്ച് തന്നെ ഉണ്ടാക്കി. ഇത് അടച്ച പ്രീ-ആൽഫയിലാണ്, അതായത് മിക്കവാറും പ്രവർത്തിക്കും, ഏതാനും സുഹൃത്തുക്കൾക്ക് വേണ്ടി. വില പേജില്ല, ന്യൂസ്‌ലെറ്ററില്ല, വളർച്ചാ പദ്ധതിയില്ല. ആരും നിങ്ങളുടെ ഡാറ്റ ശേഖരിക്കുന്നില്ല. ഉപകാരപ്രദമെന്ന് തോന്നിയാൽ, അൽപ്പം കൂടി തുറക്കുമ്പോൾ പരീക്ഷിക്കാൻ ചോദിക്കാം. ഓരോ കാർഡും ഒരു ചെറിയ ചുവടുവയ്പ്പാണ്, ഓരോ ദിവസവും ബോർഡ് കുറച്ചുകൂടി മെച്ചപ്പെടുന്നു, നിങ്ങൾ ഉറങ്ങുമ്പോൾ പോലും. നിങ്ങൾക്കും ചേരാം."]},{"n":144,"texts":["AI-gile ഒരു മനുഷ്യനും ധാരാളം AI ഏജന്റുമാർക്കുമുള്ള കാൻബൻ ബോർഡാണ്. ഇത് നിങ്ങളുടെ സ്വന്തം കമ്പ്യൂട്ടറിൽ പ്രവർത്തിക്കുന്നു, പൂർണ്ണമായും സൗജന്യമാണ്. നിങ്ങൾ പ്രോജക്റ്റുകൾ ചേർക്കുന്നു, ഓരോ പ്രോജക്റ്റിനും ഒരു ലീഡും ചെറിയ ടീമും ലഭിക്കുന്നു. Discord പോലെ ലീഡുമായി ചാറ്റ് ചെയ്ത് ഒരു ആശയം വിവരിക്കുന്നു; ലീഡ് അത് കാർഡുകളും പ്ലാനുമാക്കി, നിങ്ങൾ പോകൂ അമർത്തുന്നതുവരെ കാത്തിരിക്കുന്നു. ഭാഷാ മോഡലുകൾക്കായി ഉണ്ടാക്കിയ ഒരു ലളിതമായ കമാൻഡ് ലൈൻ ഉപയോഗിച്ച് ടീം മുൻഗണനാക്രമത്തിൽ കാർഡുകൾ ചെയ്യുന്നു. എന്തെങ്കിലും നിങ്ങളുടെ അടുത്ത് തിരിച്ചെത്തുന്നതിന് മുമ്പ്, ഒരു AI ടെസ്റ്റർ ആപ്പിന്റെ പകർപ്പിൽ ഘട്ടങ്ങൾ പിന്തുടർന്ന് ഒരു സ്ക്രീൻഷോട്ട് ചേർക്കുന്നു. പൂർത്തിയായ ജോലി മാറിയ ഫയലുകളും വ്യത്യാസവും സഹിതം നിങ്ങളുടെ കൂമ്പാരത്തിൽ എത്തുന്നു. നിങ്ങൾ സ്വീകരിക്കുന്നു, അല്ലെങ്കിൽ ഒരു കമന്റ് ഇടുന്നു, ടീം ഉണർന്ന് വീണ്ടും ശ്രമിക്കുന്നു. ബോർഡ് സ്വയം വൃത്തിയാക്കുകയും ചെയ്യുന്നു: ബന്ധപ്പെട്ട കാർഡുകൾ ഒന്നായി ലയിക്കുന്നു, കുഴഞ്ഞ തലക്കെട്ടുകൾ ശരിയാക്കുന്നു. കോഡ് ഒതുക്കത്തിൽ നിൽക്കുന്നുണ്ടോ എന്നും അത് ശ്രദ്ധിക്കുന്നു. ഇതെല്ലാം സൗജന്യമായി. നിങ്ങളുടെ ഡാറ്റ നിങ്ങളുടെ കമ്പ്യൂട്ടറിൽ തന്നെ നിൽക്കുന്നു. ഒരു കാർഡ് പൂർത്തിയായി എന്നതിലേക്ക് നീക്കാൻ നിങ്ങൾക്ക് മാത്രമേ കഴിയൂ.","AI-gile-നൊപ്പമുള്ള ഒരു ദിവസം, ഏകദേശം ഇങ്ങനെയാണ്. വൈകുന്നേരം നിങ്ങൾ കുറച്ച് കമന്റുകൾ ഇടുന്നു: ഈ ബട്ടൺ തെറ്റായ സ്ഥലത്താണ്, ആ പട്ടിക ക്രമീകരിക്കണം, ഒരു ഡാർക്ക് മോഡ് ആകാമോ. നിങ്ങൾ ഉറങ്ങാൻ പോകുന്നു. ഏജന്റുമാർ കമന്റുകൾ വായിച്ച്, മാറ്റങ്ങൾ വരുത്തി, പരീക്ഷിച്ച് നിങ്ങൾക്ക് തിരികെ നൽകുന്നു. ചെയ്യാനുള്ളത് കോളം ഒഴിഞ്ഞാൽ, നിങ്ങളുടെ ഉത്തരം ആവശ്യമില്ലാത്ത കാർഡുകൾ കൊണ്ട് രാത്രി കാവൽ ബാക്ക്‌ലോഗിൽ നിന്ന് അത് നിറയ്ക്കുന്നു. രാവിലെ ഒരു ചെറിയ കൂമ്പാരം ഉണ്ടാകും: രണ്ട് ചോദ്യങ്ങളും പരീക്ഷിക്കാൻ ചിലതും, ഓരോന്നിനും ഉറക്കച്ചടവുള്ള ഒരാൾക്ക് പിന്തുടരാവുന്ന ഘട്ടങ്ങളും പ്രവർത്തിക്കുന്നതിന്റെ സ്ക്രീൻഷോട്ടും. നിങ്ങൾ ക്ലിക്ക് ചെയ്ത് നല്ലവ സ്വീകരിക്കുന്നു, ബാക്കിയുള്ളവ തിരിച്ചയയ്ക്കുന്നു. ചില കമന്റുകൾക്ക് ഏജന്റുമാർ ചോദ്യങ്ങളും തിരിച്ചയയ്ക്കും; അത് മറ്റൊരു ദിവസം ശാന്തമായി ഉത്തരം നൽകാം. എന്തെങ്കിലും വ്യക്തമല്ലെങ്കിൽ ഒരു കമന്റ് ഇട്ടാൽ മതി, അത് വീണ്ടും ടീമിന്റെ അടുത്തെത്തും. ഇത്രയേ ഉള്ളൂ, അതിനിടയിൽ നിങ്ങൾക്ക് സ്വന്തം ജീവിതം നയിക്കാം. ഇതെല്ലാം എത്ര ഉപയോഗിച്ചെന്ന് ടോക്കൺ കൗണ്ടർ കാണിക്കുന്നു, ലാഭിക്കേണ്ട ആഴ്ചകൾക്ക് ടോക്കൺ ഇല്ലാ മോഡ് ഉണ്ട്. പിന്നെ നിങ്ങൾ പ്രഭാതഭക്ഷണം കഴിക്കുന്നു, അതിൽ ഏജന്റുമാർക്ക് ഇതുവരെ സഹായിക്കാനാവില്ല.","ആദ്യം, AI-gile എന്തല്ല എന്ന് പറയാം. ഇത് സ്റ്റാർട്ടപ്പല്ല, വിൽപ്പനയ്ക്കുള്ളതല്ല, ആരും നിങ്ങളുടെ ഡാറ്റ ശേഖരിക്കുന്നില്ല. ഇത് നിങ്ങളുടെ കമ്പ്യൂട്ടറിൽ പ്രവർത്തിക്കുന്ന സൗജന്യ ബോർഡാണ്, അക്കൗണ്ടില്ല, ട്രാക്കറുകളില്ല, കുക്കികളില്ല. പിന്നെ ഇത് എന്താണ്: എല്ലാ AI കോഡിങ് പ്രോജക്റ്റുകളും ഒരേസമയം കാണാനുള്ള ഒരു വൃത്തിയുള്ള സ്ഥലം, കാർഡുകൾ ചെയ്യുന്നത് ഏജന്റുമാരുടെ ടീം, തീരുമാനങ്ങൾ എടുക്കുന്നത് നിങ്ങൾ. നിങ്ങൾ ഉറങ്ങുമ്പോൾ കാർഡുകൾ ഒരുക്കുന്ന രാത്രി കാവലും ഉണ്ട്. ബന്ധപ്പെട്ട കാർഡുകൾ ഒന്നാക്കുന്നു, കുഴഞ്ഞ തലക്കെട്ടുകൾ ശരിയാക്കുന്നു, കോഡ് ഒതുക്കത്തിൽ നിൽക്കുന്നുണ്ടോ എന്ന് ശ്രദ്ധിക്കുന്നു. ഡച്ചും ഫ്ലെമിഷും മുതൽ കടൽക്കൊള്ളക്കാരനും ക്ലിംഗണും വരെ ഏകദേശം 120 ഭാഷകൾ ഇത് സംസാരിക്കുന്നു. സുഹൃത്തുക്കൾക്ക് പരസ്പരം സ്വകാര്യമായും എൻക്രിപ്റ്റ് ചെയ്തും സന്ദേശം അയയ്ക്കാം. Rich-ഉം ക്ഷമയുള്ള ഒരുപാട് ഏജന്റുമാരും ചേർന്ന്, മിക്കവാറും ബോർഡ് ഉപയോഗിച്ച് തന്നെ ഇത് നിർമ്മിച്ചു. ഇത് അടച്ച പ്രീ-ആൽഫയിലാണ്, അതിനാൽ ചിലയിടങ്ങളിൽ പരുക്കനാണ്. ഓരോ കാർഡിനും പിന്നിൽ എന്താണ് സംഭവിച്ചതെന്ന് കാണാം, നിങ്ങൾക്ക് ഇഷ്ടമുള്ളപ്പോൾ മാത്രം. ഒരു പരസ്യവും ഒരു വില പേജും പോലും ഇല്ല. രസകരമായി തോന്നിയാൽ മര്യാദയോടെ ചോദിക്കൂ, നേരത്തെ കയറാൻ കഴിഞ്ഞേക്കും."]}],"quips":{"1":"ഒരു വാക്ക്. ധീരം. ഒരുപക്ഷേ അൽപ്പം കൂടുതൽ ധീരം.","3":"മൂന്ന് വാക്കുകൾ. മിക്ക പ്രൊഡക്റ്റ് പേജുകളേക്കാളും സത്യസന്ധം.","8":"എട്ട് വാക്കുകൾ. ഒരു സ്റ്റാൻഡ്-അപ്പിനേക്കാൾ ഇപ്പോഴും ചെറുത്.","21":"നീളങ്ങൾ സ്റ്റോറി പോയിന്റുകളാണ്, ഇടയ്ക്ക് പറയട്ടെ. പിന്നല്ലാതെ.","55":"അൻപത്തഞ്ച് വാക്കുകൾ. നിങ്ങൾ ഇത് വായിച്ചപ്പോഴേക്കും രണ്ട് കാർഡുകൾ തീർന്നു.","144":"ഇതാണ് നീളമുള്ളത്. 233 ഇല്ല. ഏജന്റുമാർ ഉറങ്ങാൻ പോയി."}},"timeline":{"first-idea.name":"ആദ്യ ആശയം","first-idea.line":"ഒരു വരി കോഡ് പോലും ഉണ്ടാകുന്നതിന് മുമ്പുള്ള ആദ്യത്തെ സംഭാഷണം.","first-board.name":"ആദ്യ ബോർഡ്","first-board.line":"സ്വന്തം നിർമ്മാണം പിന്തുടരുന്ന ബോർഡ്: കാർഡുകൾ, കോളങ്ങൾ, ഡ്രാഗ് ആൻഡ് ഡ്രോപ്പ്, പ്രോജക്റ്റുകൾ.","team-roles.name":"ടീമും റോളുകളും","team-roles.line":"ഏജന്റ് പ്രൊഫൈലുകൾ, ടീം ടെംപ്ലേറ്റുകൾ, സ്പേസുകൾ, ആരാണ് എന്തു ചെയ്യുന്നു.","install.name":"ഇൻസ്റ്റാളും റിലീസുകളും","install.line":"സുഹൃത്തിന് ഇൻസ്റ്റാൾ ചെയ്യാവുന്ന ഒരു സിപ്പ്, സ്വയം അപ്ഡേറ്റ്, ചാനലുകൾ, പഴയതിലേക്ക് മടക്കം.","usage-saver.name":"ഉപയോഗ സേവർ","usage-saver.line":"ഓരോ റണ്ണിനും എത്ര ചെലവെന്ന് അളക്കുക, കോഡ് ഒതുക്കത്തിൽ നിർത്തുക, പരിധി ലാഭിക്കുക.","friends.name":"സുഹൃത്തുക്കളും പങ്കിടലും","friends.line":"സ്വകാര്യ DM-കൾ, കലക്കിയ റിലേ, ക്ഷണങ്ങൾ, റോളുകൾ, പങ്കിട്ട പ്രോജക്റ്റുകൾ.","languages.name":"ഭാഷകൾ","languages.line":"ഓരോ സ്ക്രീൻ വാചകവും ഒരു ഭാഷാ ഫയലിൽ, ആദ്യം ഡച്ചും ഫ്ലെമിഷും.","ai-tester.name":"AI ടെസ്റ്റർ","ai-tester.line":"ഓരോ കൈമാറ്റവും ആദ്യം ഒരു ടെസ്റ്റർ പരിശോധിച്ച് കണ്ടത് കാണിക്കുന്നു.","website.name":"വെബ്സൈറ്റ്","website.line":"aigile.lol, ടീസർ, ഈ സമയരേഖ.","streaming.name":"ചാറ്റും സ്ട്രീമിങ്ങും","streaming.line":"Discord, Twitch, OBS, സ്ട്രീമർ മോഡ്, GIF-കൾ, ഇമോജികൾ.","no-ai.name":"AI ഇല്ലാത്ത പതിപ്പ്","no-ai.line":"AI ഇല്ലാതെ കോഡ് ചെയ്യുന്നവർക്കുള്ള ബോർഡ്, പൊതു ബോർഡുകളും.","night-watch.name":"രാത്രി കാവൽ","night-watch.line":"നിങ്ങൾ ഉറങ്ങുമ്പോൾ ഒരു കാവൽക്കാരനും Scrum Master-ഉം ടീമുകളെ ജോലിയിൽ നിർത്തുന്നു.","p-more.name":"ബാക്കിയെല്ലാം","p-more.line":"ഊഴം കാത്തിരിക്കുന്ന ചെറിയ ആശയങ്ങൾ.","p-android.name":"ഫോണും ആൻഡ്രോയിഡും","p-android.line":"ഫോണിൽ നിന്ന് ബോർഡിൽ എത്തുക, പിന്നെ ഒരു നേറ്റീവ് ആൻഡ്രോയിഡ് ആപ്പ്.","p-release.name":"ആൽഫയും അതിനപ്പുറവും","p-release.line":"അടച്ച ആൽഫ, ലൈവ് സൈറ്റ്, പിന്നെ ബീറ്റ.","p-languages.name":"കൂടുതൽ ഭാഷകൾ","p-languages.line":"നൂറിലധികം ഭാഷകൾ, പഠിതാക്കൾക്കായി ഒരു ഇമ്മേഴ്ഷൻ മോഡ്.","p-engines.name":"കൂടുതൽ AI എഞ്ചിനുകൾ","p-engines.line":"ഓരോ ഏജന്റിനും Claude, Codex അല്ലെങ്കിൽ Gemini തിരഞ്ഞെടുക്കുക.","p-pro.name":"പ്രൊഫഷണൽ രീതികൾ","p-pro.line":"റിസ്ക് ലേബലുകൾ, മെർജ് ഗേറ്റുകൾ, ഇൻസിഡന്റ് കാർഡുകൾ, ഗാർഡ് റെയിലുകൾ.","p-self.name":"നിങ്ങളെ ശ്രദ്ധിക്കൽ","p-self.line":"ക്ഷീണ മോഡ്, സ്വയം പരിചരണ ഓർമ്മപ്പെടുത്തലുകൾ, 4:20.","p-servers.name":"സെർവറുകളും വളർച്ചയും","p-servers.line":"ആഗോള സെർവർ ക്രമീകരണങ്ങൾ, റോളുകൾ, വളർച്ചയ്ക്കുള്ള ആസൂത്രണം.","p-livestream.name":"സ്ട്രീമിങ് അധികങ്ങൾ","p-livestream.line":"Twitch ചാറ്റ്, സ്വന്തം ഇമോജികൾ, പൊതു ലൈവ് കാഴ്ച."}};
